test('issueInvoice uses nextInvoiceNumber to find the next available number', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
