      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 2, unitPrice: 980, vatRate: 21 },
    ],
  };
  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 2, unitPrice: 980, vatRate: 21 },
    ],
  };
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(invoice, invoiceCopy);
});
